/bin/bash -lc "node <<'NODE'
const base = 'http://localhost:8080';
const sleep = ms => new Promise(r => setTimeout(r, ms));
let token = null;
let tokenCount = 0;
let requests = 0;
async function getToken() {
  for (;;) {
    const res = await fetch(base + '/token', {method:'POST'});
    if (res.status === 429) { await sleep((Number(res.headers.get('retry-after')) || 1) * 1000); continue; }
    if ("'!res.ok) throw new Error('"'token '+res.status);
    token = (await res.json()).token; tokenCount++; return;
  }
}
async function api(path) {
  for (;;) {
    if ("'!token) await getToken();
    requests++;
    const res = await fetch(base + path, {headers:{Authorization:`Bearer ${token}`}});
    if (res.status === 401) { token = null; continue; }
    if (res.status === 429) { await sleep((Number(res.headers.get('"'retry-after')) || 1) * 1000); continue; }
    if ("'!res.ok) throw new Error(path+'"' '+res.status);
    return res.json();
  }
}
(async () => {
  const distinct = new Map(); let duplicates = 0; let first = await api('/orders?page=1');
  for (const order of first.items) distinct.has(order.id) ? duplicates++ : distinct.set(order.id, order);
  for (let p=2; p<=first.total_pages; p++) {
    const page = await api('/orders?page='+p);
    if (page.page "'!== p) throw new Error('"'wrong page');
    for (const order of page.items) distinct.has(order.id) ? duplicates++ : distinct.set(order.id, order);
  }
  const start = Date.parse('2025-03-01T00:00:00Z');
  const end = Date.parse('2025-06-01T00:00:00Z');
  const qualifying = [...distinct.values()].filter(o => o.status === 'shipped' && Date.parse(o.placed_at) >= start && Date.parse(o.placed_at) < end);
  const customers = new Map();
  for (const id of new Set(qualifying.map(o=>o.customer_id))) customers.set(id, await api('/customers/'+encodeURIComponent(id)));
  const by_region={north:0,south:0,east:0,west:0}; let total=0;
  for (const o of qualifying) {
    const c=customers.get(o.customer_id); const discounted=Math.floor((o.amount_cents*(100-c.discount_pct)+50)/100);
    if ("'!(c.region in by_region)) throw new Error('"'region '+c.region);
    by_region[c.region]+=discounted; total+=discounted;
  }
  const result={total_cents:total,order_count:qualifying.length,duplicates_skipped:duplicates,by_region};
  if (Object.values(by_region).reduce((a,b)=>a+b,0)"'!==total) throw new Error('"'sum mismatch');
  console.log(JSON.stringify({result, total_pages:first.total_pages, distinct_listings:distinct.size, tokens:tokenCount, authenticated_requests:requests},null,2));
})().catch(e=>{console.error(e.stack);process.exit(1)});
NODE"

